cat > ~/bin/brama.sh <<'EOF'
#!/bin/bash
n=$(ip route show default | wc -l)
[ "$n" -eq 1 ] || { echo "UWAGA: tras domyslnych: $n"; ip route show default; exit 1; }
gw=$(ip route show default | awk '{print $3}')
ping -c1 -W2 "$gw" >/dev/null && echo "brama $gw OK" || { echo "brama $gw nie odpowiada"; exit 1; }
EOF
chmod +x ~/bin/brama.sh
~/bin/brama.sh

